  EXPECT_EQ(parse_number("-0xfffffffffffffffe00000000000000000000000000000002", nullptr), parse_number("-0xfffffffffffffffe00000000000000010000000000000000", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000002", nullptr)));
