  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0x10000000000000001", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0x1", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0x10000000000000001", nullptr), parse_number("-0x10000000000000001", nullptr).logical_or(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
