  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr), parse_number("0x1ffffffffffffffff", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
