  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr), parse_number("0xfffffffffffffffeffffffffffffffff", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
