  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000000fffffffffffffffd", nullptr), parse_number("0xffffffffffffffff0000000000000002", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
