  EXPECT_EQ(parse_number("-0xfffffffffffffffdffffffffffffffff0000000000000001", nullptr), parse_number("0x20000000000000000ffffffffffffffff", nullptr).logical_or(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
