  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000001", nullptr), parse_number("0xffffffffffffffff0000000000000000fffffffffffffffe", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000002", nullptr), parse_number("0xffffffffffffffff0000000000000000fffffffffffffffe", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000002", nullptr), parse_number("0xffffffffffffffff0000000000000000fffffffffffffffe", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000001", nullptr), parse_number("0xffffffffffffffff0000000000000000fffffffffffffffe", nullptr).logical_or(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
